// Verifica se a BrasilAPI retornou dados válidos
const j = $input.first().json || {};

// HTTP Request com neverError retorna o body mesmo em erro
// Erros da BrasilAPI: { message: '...', type: 'not_found' }
// Sucesso: tem cnae_fiscal, razao_social, etc.
const isApiError = j.message || j.type || j.error;
const hasValidData = j.razao_social || j.cnae_fiscal;

if (isApiError && !hasValidData) {
  const msg = j.message || j.type || 'BrasilAPI sem dados';
  return [{ json: { success: false, error: msg, source: 'BrasilAPI' } }];
}

return [{ json: { ...j, _source: 'brasilapi' } }];

// Verifica se o CNPJ.ws retornou dados válidos
const j = $input.first().json || {};

// CNPJ.ws erro: { status: 404, titulo: '...', detalhes: '...' }
// CNPJ.ws sucesso: tem cnpj_raiz, razao_social, estabelecimento
const isApiError = j.status || j.titulo || j.detalhes;
const hasValidData = j.razao_social || j.cnpj_raiz;

if (isApiError && !hasValidData) {
  const msg = j.detalhes || j.titulo || 'CNPJ.ws sem dados';
  return [{ json: { success: false, error: msg, source: 'CNPJ.ws' } }];
}

return [{ json: { ...j, _source: 'cnpjws' } }];

const r = $input.first().json || {};
const { payload, ...rest } = r;
return [{ json: { ok:true, data: rest, error:null } }];

