// Classifica a falha para dar uma mensagem acionável.
const input = $input.first().json || {};
const errText = String(input.error || input.message || '');
const source = input.source || 'desconhecida';

const is404 = /404|n[aã]o encontrad|not.found/i.test(errText);
const is429 = /429|too.many.requests|rate.limit/i.test(errText);
const isTimeout = /timeout|ETIMEDOUT|ECONNABORTED|ECONNREFUSED|ENOTFOUND|EAI_AGAIN/i.test(errText);

let msg;
if (is404) {
  msg = `CNPJ não encontrado na ${source}. Verifique se o número está correto.`;
} else if (is429) {
  msg = `Limite de consultas da ${source} atingido. Tente novamente em alguns minutos.`;
} else if (isTimeout) {
  msg = `Serviço da ${source} está lento ou indisponível. Tente novamente em instantes.`;
} else {
  msg = `Consulta via ${source} falhou: ${errText || 'API indisponível'}`;
}

return [{ json: { ok: false, data: null, error: msg, source } }];
